#!/usr/bin/env python3
"""Regenerate portable YAML fixture tests from the pinned upstream data checkout."""
import json
from pathlib import Path
import subprocess
import sys

REVISION = "6ad3d2c62885d82fc349026c136ef560838fdf3d"
SUPPORTED = "2AUY 6FWR 4CQQ A6F9 8XYN AVM7 6KGN 35KP 6JWB 74H7 7ZZ5 D88J DHP8 FUP4 6VJK F8F9 K858 5KJE".split()
UNSUPPORTED = "7FWL C4HZ".split()
INVALID = "4H7K 6JTT 9MAG CTN5 55WF SF5V QB6E".split()
root = Path(__file__).resolve().parents[2]
checkout = Path(sys.argv[1])
revision = subprocess.check_output(["git", "-C", str(checkout), "rev-parse", "HEAD"], text=True).strip()
if revision != REVISION:
    raise SystemExit(f"Expected {REVISION}, got {revision}")
lines = ["// Generated by .github/scripts/generate_yaml_fixtures.py.",
         f"// yaml/yaml-test-suite data revision {REVISION}.",
         "// MIT, Copyright (c) 2016-2020 Ingy döt Net. See fixtures/LICENSE."]
for classification, ids in [("supported", SUPPORTED), ("unsupported", UNSUPPORTED), ("invalid", INVALID)]:
    for case in ids:
        folder = checkout / case
        source = (folder / "in.yaml").read_bytes().decode("utf-8")
        title = (folder / "===").read_text().strip()
        lines += ["", "///|", f"// {title}", f'test "yaml-test-suite {case}: {classification}" {{',
                  f"  let source = {json.dumps(source, ensure_ascii=False)}"]
        if classification == "supported":
            expected = (folder / "in.json").read_text() if (folder / "in.json").exists() else ""
            lines += [f"  let expected = @ion.read_text({json.dumps(expected, ensure_ascii=False)})",
                      '  let actual = @yaml.read_text(source) catch { e => fail(e.message()) }',
                      '  @expect.expect(actual).to_equal(expected)']
        else:
            kind = "Unsupported" if classification == "unsupported" else "Syntax"
            lines += ['  @expect.expect_call(() => @yaml.read_text(source)).to_raise_matching(',
                      f'    e => e is @yaml.YamlError::YamlError(kind={kind}, ..), description="{case} {classification}",', '  )']
        lines.append('}')
(root / "modules/partiql-value/src/yaml/upstream_test.mbt").write_text("\n".join(lines) + "\n")
